public Book updateBook(Long id, BookUpdateRequest request) {
    Book book = getBookById(id);           // SELECT 쿼리 실행
    // title: "1984"

    book.updateBookInfo("New Title", ...); // SQL 실행 안 됨 (메모리만 변경)
    // title: "New Title"

    System.out.println("메서드 종료 직전");

    return book;  // 여기서 메서드 종료
}
// 👆 이 시점에 UPDATE 쿼리 자동 실행!
// UPDATE books SET title = 'New Title' WHERE id = 1;

