@Transactional
public Book updateBook(Long id, BookUpdateRequest request) {
    Book book = getBookById(id);
    book.updateBookInfo("New Title", ...);  // 메모리상 변경

    // 중복 체크에서 예외 발생!
    if (bookRepository.existsByTitle("New Title")) {
        throw new DuplicateBookException("중복된 제목");
    }

    return book;  // 여기 도달 못함
}
// 👆 예외 발생 → 롤백
// UPDATE 쿼리 실행 안 됨
// DB는 변경 전 상태 유지 ("1984" 그대로)

